import{_ as t,o,c as r,a0 as n}from"./chunks/framework.DNNiP2TX.js";const l=JSON.parse('{"title":"@shutter-network/concorde/signatures routes","description":"","frontmatter":{"title":"@shutter-network/concorde/signatures routes"},"headers":[],"relativePath":"reference/routes/signatures.md","filePath":"reference/routes/signatures.md"}'),s={name:"reference/routes/signatures.md"};function a(i,e,d,c,h,g){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="shutter-network-concorde-signatures" tabindex="-1">@shutter-network/concorde/signatures <a class="header-anchor" href="#shutter-network-concorde-signatures" aria-label="Permalink to &quot;@shutter-network/concorde/signatures&quot;">​</a></h1><p>The HTTP routes this component serves: 1 on the Agent server and 2 on the Public server.</p><p><strong>Every path is relative.</strong> Each one is printed as the plugin declares it, under whatever prefix the component&#39;s constructor registers that plugin at. This page states no mount point, because the constructor is where the mount point is decided.</p><p>Generated from what the route plugins in <code>src/signatures/routes.ts</code> declare, which is what a running Gateway serves at <code>GET /openapi.json</code>. Never edited by hand.</p><h2 id="agent-server" tabindex="-1">Agent server <a class="header-anchor" href="#agent-server" aria-label="Permalink to &quot;Agent server&quot;">​</a></h2><p><strong>The Agent server has no authentication of any kind.</strong> Everything below is reachable by the agent, and therefore by an injected prompt (<a href="https://github.com/shutter-network/concorde/blob/main/docs/adr/0003-prompt-injection-is-an-accepted-risk.md" target="_blank" rel="noreferrer">ADR-0003</a>). Nothing on it names a credential.</p><h3 id="post-sign" tabindex="-1"><code>POST /sign</code> <a class="header-anchor" href="#post-sign" aria-label="Permalink to &quot;`POST /sign`&quot;">​</a></h3><p><strong>Sign a Statement</strong></p><p>Have any string signed with the shared agent&#39;s key, and receive one compact JWS back. <strong>Nothing is stored.</strong> There is no row afterwards and no route that lists what has been signed, so the artifact answered is the whole of what happened. Losing it means signing again. A commitment worth keeping is a Decision: <code>POST /decisions</code> signs it too, and numbers it, and keeps it.</p><p>The <code>typ</code> is yours, and <strong>nothing is reserved</strong>. Asking for <code>concorde-decision+jws</code> here is allowed and is not a forgery. Publishing a Decision is an authority you already hold, so a decision-typed artifact minted here is that same authority exercised without a log row. What it is <em>not</em> is a promise to a verifier. <code>typ</code> is your signed claim about your own artifact, and only an artifact fetched from <code>GET /decisions</code> is guaranteed to be shaped like one.</p><p>The Statement has no length limit of ours. The server&#39;s own body limit is the bound, and it belongs to the Operator. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Signatures</code>.</p><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><p><strong><code>statement</code></strong> <code>string</code>, required, at least 1 character</p></li><li><p><strong><code>typ</code></strong> <code>string</code>, optional, 1 to 128 characters, default <code>&quot;concorde-statement+jws&quot;</code></p><p>What kind of thing this artifact is. It goes into the <strong>protected header</strong>, so the signature covers it. Swapping it invalidates the artifact, which keeps a receipt from being presented as an approval.</p><p><strong>Any label, <code>concorde-decision+jws</code> included.</strong> Domain separation between your <em>own</em> categories, such as receipts, votes and approvals, is something only you can express. Give each of them a label of its own, or they collapse into one domain and become replayable as each other. Defaults to <code>concorde-statement+jws</code>.</p></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The Signed Statement, which is the whole answer: this part kept no copy of it and no record that it was made, beyond one line in the log carrying the <code>typ</code> and a digest.</p><ul><li><p><strong><code>jws</code></strong> <code>string</code>, required</p><p>The <strong>Signed Statement</strong>: a compact JWS, <code>header.payload.signature</code>, base64url, one URL-safe string. Its payload is <code>{&quot;statement&quot;:…}</code> and nothing else, with no number and no timestamp, both of those being a Decision&#39;s. Its protected header carries the algorithm and the <code>typ</code> that was asked for. Nothing was stored: this string is the whole of what happened, so keep it or hand it on.</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p><code>statement</code> is missing or empty, <code>typ</code> is empty or longer than 128 characters, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h2 id="public-server" tabindex="-1">Public server <a class="header-anchor" href="#public-server" aria-label="Permalink to &quot;Public server&quot;">​</a></h2><p><strong>The Public server is what a User&#39;s client calls.</strong> Which credential each route wants, and which wants none, is in that route&#39;s own description below.</p><h3 id="get-jwks-json" tabindex="-1"><code>GET /jwks.json</code> <a class="header-anchor" href="#get-jwks-json" aria-label="Permalink to &quot;`GET /jwks.json`&quot;">​</a></h3><p><strong>Fetch the shared agent&#39;s public key</strong></p><p>The shared agent&#39;s public key, as a JWK Set (RFC 7517). It is what makes a Signed Statement checkable <strong>without trusting this Gateway</strong>. Fetch it once, keep it, and verify artifacts offline with any JOSE library in any language. That is the real verification path, and the only one worth anything to somebody who does not trust the Operator.</p><p>One keypair, always, so the set holds one key. There is no rotation, no key identifier and nothing to select between. What a valid signature proves is narrow. <strong>The Operator committed to this Statement on the shared agent&#39;s behalf.</strong> It says nothing whatever about how the agent behaved.</p><p><strong>No Token is required</strong>, a public key being public. Besides the login itself, this is the one route on the Public server that asks for none. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Signatures</code>.</p><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The key set, holding the one key this shared agent signs with. It carries <strong>no private member</strong>: the schema is a positive list of public ones, so there is nothing here to keep secret and nothing to send it over TLS for.</p><ul><li><strong><code>keys</code></strong> array of <code>object</code>, required <ul><li><p><strong><code>kty</code></strong> <code>string</code>, required</p><p>The key type, in JOSE&#39;s own vocabulary rather than OpenSSL&#39;s: <code>OKP</code> for an Edwards key, <code>EC</code> for a NIST curve, <code>RSA</code> for an RSA key.</p></li><li><p><strong><code>crv</code></strong> <code>string</code>, optional</p></li><li><p><strong><code>x</code></strong> <code>string</code>, optional</p></li><li><p><strong><code>y</code></strong> <code>string</code>, optional</p></li><li><p><strong><code>n</code></strong> <code>string</code>, optional</p></li><li><p><strong><code>e</code></strong> <code>string</code>, optional</p></li></ul></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>A query parameter was written, and this route takes none.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="post-verify" tabindex="-1"><code>POST /verify</code> <a class="header-anchor" href="#post-verify" aria-label="Permalink to &quot;`POST /verify`&quot;">​</a></h3><p><strong>Check whether an artifact is this shared agent&#39;s</strong></p><p>A convenience, and <strong>it proves less than it looks like it proves</strong>. It answers one question: is this artifact this shared agent&#39;s? You have to believe the answer, because a dishonest Gateway says <code>true</code> to anything. So it is worth nothing to the party this identity exists for. That party does not trust the Operator. It is genuinely useful to a User, who trusts the Operator already. They want a quick confirmation without embedding a JOSE library.</p><p><strong>Real verification is offline.</strong> Fetch <code>GET /jwks.json</code> once, keep the key, and check the artifact yourself in whatever language you are already writing. That asks this Gateway nothing. The path is open to anybody holding the string, needs no Token, and keeps working after this deployment is gone.</p><p>Answers <strong>200 either way</strong>. An artifact that is not ours is a <code>false</code> and not an error. That covers a foreign identity&#39;s artifact, a tampered one and a wrong number of segments. Malformed base64url and an unparseable header get the same answer. All of those arrive from a caller, and none of them is this Gateway failing. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Signatures</code>.</p><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><strong><code>jws</code></strong> <code>string</code>, required, at least 1 character</li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The verdict, and the artifact&#39;s own header and payload when it is ours. Both of those are read out of the bytes the signature covers, so they are what was signed rather than what was posted.</p><ul><li><p><strong><code>verified</code></strong> <code>boolean</code>, required</p><p>Whether this artifact carries a valid signature by <strong>this</strong> shared agent&#39;s key. <code>false</code> covers every way of not being ours at once: another identity&#39;s artifact, a tampered one, a wrong number of segments, malformed base64url and an unparseable header alike. None of them is an error, so none of them is a 4xx.</p></li><li><p><strong><code>header</code></strong> any JSON, optional</p><p>The protected header the signature covers, as it was written: the algorithm, and the <code>typ</code> the signer chose. <strong><code>typ</code> is that signer&#39;s own claim about its artifact and not a guarantee of this framework&#39;s</strong>. A <code>&quot;concorde-decision+jws&quot;</code> here means this identity labelled it a Decision, not that it is shaped like one and not that a row exists. Only an artifact fetched from <code>GET /decisions</code> is guaranteed well-formed.</p></li><li><p><strong><code>payload</code></strong> any JSON, optional</p><p>The claims the signature covers, parsed out of the bytes that were signed. A Statement signed at <code>POST /sign</code> carries <code>{ statement }</code>; a Decision carries <code>{ seq, createdAt, statement }</code>, so everything a Decision record holds can be read back out of the artifact alone.</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p><code>jws</code> is missing or empty, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists. This part authenticates nobody: the refusal is <code>publicServer.requireUser</code>, taken as one option on the route, so it is the same 401 every protected route on this server answers, whichever scheme the deployment accepts.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul>',56)])])}const u=t(s,[["render",a]]);export{l as __pageData,u as default};
